import json
from pathlib import Path
p=Path(__file__).parent/'chunks/0002.json';d=json.loads(p.read_text())
translations={
 't000013': '''Reprezentarea controlului totalitar din „1984” este un avertisment sever cu privire la posibilitatea abuzului de putere în orice societate. Examinând mecanismele de control folosite în Oceania, putem înțelege mai bine fragilitatea libertății individuale și importanța vigilenței pentru protejarea valorilor democratice. Romanul ne obligă să înfruntăm întrebări incomode despre natura puterii și despre capacitatea oamenilor atât de a rezista, cât și de a se supune.''',
 't000014': 'Capitolul al doilea: Limbajul și manipularea gândirii',
 't000015': '''În „1984”, George Orwell prezintă limbajul ca pe un instrument puternic de control al gândirii și de modelare a realității. Partidul din Oceania folosește manipularea limbajului ca strategie esențială pentru a-și păstra puterea și a înăbuși opoziția.''',
 't000016': '''În centrul controlului lingvistic al Partidului se află Nouvorba, limba oficială a Oceaniei. Nouvorba nu este concepută să extindă, ci să restrângă sfera gândirii. Principiul ei de bază este că, pe măsură ce o limbă are mai puține cuvinte, se îngustează și gama gândurilor posibile. Această limbă artificială se caracterizează prin gramatică și vocabular simplificate, eliminarea nuanțelor și ambiguității, înlăturarea cuvintelor legate de libertate, rebeliune ori individualitate și crearea unor cuvinte compuse care exprimă idei complexe în forme simplificate.''',
 't000017': '''De exemplu, cuvântul „liber” există în Nouvorbă doar în expresii precum „Acest câine este liber de păduchi” sau „Acest câmp este liber de buruieni”. Ideea de libertate politică sau intelectuală a fost eliminată cu totul din limbă. Scopul final al Nouvorbei este ca delictul de gândire, adică gândurile opuse doctrinei Partidului, să devină literalmente imposibil. După cum îi explică lui Winston Syme, un lingvist care lucrează la dicționarul Nouvorbei: „Nu vezi că întregul scop al Nouvorbei este să restrângă sfera gândirii? În cele din urmă vom face delictul de gândire literalmente imposibil, pentru că nu vor mai exista cuvinte în care să-l exprimi.”''',
 't000018': '''Controlând limbajul, Partidul limitează efectiv capacitatea cetățenilor de a gândi critic sau de a-și exprima dezacordul. Fără cuvinte pentru a formula idei complexe ori nuanțate, capacitatea de gândire abstractă a oamenilor se reduce drastic. Controlul lingvistic depășește vocabularul și ajunge la însăși structura limbii. Nouvorba este concepută pentru a face anumite gânduri nu doar greu de exprimat, ci imposibile la nivel conceptual. Reducerea limbajului simplifică și standardizează tiparele de gândire. Având la dispoziție mai puține cuvinte, ideile devin mai categorice, iar Partidul poate controla mai ușor relatarea și interpretarea evenimentelor.''',
 't000019': '''Manipularea limbajului de către Partid este poate cel mai vizibilă în lozinci și propagandă. Cele trei lozinci principale o concentrează: „Războiul este pace”, „Libertatea este sclavie” și „Ignoranța este putere”. Aceste afirmații paradoxale exemplifică dublugânditul, capacitatea de a susține simultan două convingeri contradictorii. Repetând mereu lozincile, Partidul îi condiționează pe cetățeni să accepte contradicțiile logice fără să le pună la îndoială.''',
 't000020': '''Propaganda din Oceania este omniprezentă și inevitabilă. Afișele, emisiunile și chiar literatura pentru copii sunt saturate de ideologia Partidului. Acest bombardament continuu cu mesaje atent construite modelează gândurile și percepțiile oamenilor la nivel subconștient.''',
 't000021': '''Controlul Partidului asupra limbajului se extinde prin monopolul său asupra informației și educației. Toate știrile, materialele de divertisment și cele educaționale sunt produse și controlate de Partid. Astfel, acesta poate influența nu doar cum gândesc oamenii, ci și la ce se gândesc. Documentele istorice sunt rescrise mereu pentru a corespunde relatării actuale a Partidului. Munca lui Winston la Ministerul Adevărului constă în modificarea articolelor vechi de ziar astfel încât să se potrivească versiunii curente a evenimentelor. Revizuirea continuă a istoriei îi privează pe cetățeni de un reper stabil după care să judece afirmațiile Partidului.''',
 't000022': '''Educația din Oceania este concepută nu pentru a transmite cunoștințe, ci pentru a insufla doctrina Partidului. Gândirea critică și cercetarea independentă sunt descurajate sau interzise de-a dreptul. În schimb, accentul cade pe memorarea mecanică a faptelor și lozincilor aprobate de Partid.''',
 't000023': '''Scopul pe termen lung al controlului lingvistic exercitat de Partid este o populație incapabilă de gândire independentă. Limitând limbajul, conducătorii urmăresc să limiteze însăși capacitatea de a gândi complex sau abstract. Consecințele pentru identitatea individuală și pentru societate în ansamblu sunt profunde.''',
}
assert set(translations)=={x['id'] for x in d['segments']}
for seg in d['segments']:seg['translation']=translations[seg['id']]
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('translated',len(d['segments']))
